<template><section class="container py-4 context-page"><h1>{{ tr('Abrir módulo','Open module') }} · {{ title }}</h1><p>{{ tr('Selecciona la iglesia y la vista de trabajo. Las acciones respetan los permisos configurados para esa iglesia.','Select the church and working view. Actions follow the permissions configured for that church.') }}</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><form @submit.prevent="open"><fieldset :disabled="busy"><label>{{ tr('Iglesia','Church') }}<select v-model="churchId" class="form-select" required><option value="">{{ tr('Seleccionar','Select') }}</option><option v-for="church in churches" :key="church.id" :value="church.id">{{ church.name }}</option></select></label><label>{{ tr('Vista de trabajo','Working view') }}<select v-model="view" class="form-select"><option value="secretary">{{ tr('Secretaría','Clerk') }}</option><option value="pastor">Pastor</option><option value="department">{{ tr('Departamento','Department') }}</option></select></label><label v-if="view==='department'">{{ tr('Departamento','Department') }}<select v-model="departmentId" class="form-select" required :disabled="loadingDepartments"><option value="">{{ tr('Seleccionar','Select') }}</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.name }}</option></select></label><button class="btn btn-primary" :disabled="!churchId || loadingDepartments">{{ tr('Abrir','Open') }} {{ title }}</button></fieldset></form></section></template>
<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../../stores/authStore'
import {useUiStore} from '../../stores/uiStore'
import {superAdminApi} from '../../services/superAdminApi'
const auth=useAuthStore(),ui=useUiStore(),route=useRoute(),router=useRouter(),tr=(es,en)=>ui.locale==='es'?es:en
const churchId=ref(''),departmentId=ref(''),churches=ref([]),departments=ref([]),busy=ref(false),loadingDepartments=ref(false),error=ref(''),view=ref('secretary')
const module=computed(()=>auth.accessModules[route.query.module]),title=computed(()=>module.value?.[ui.locale==='es'?'es':'en'] || '')
watch(()=>route.query.module,key=>{view.value=key==='members'?'pastor':['inventory','objectives','budget','meeting_points'].includes(key)?'department':'secretary';error.value=''}, {immediate:true})
let generation=0
watch(churchId,async id=>{const version=++generation;departmentId.value='';departments.value=[];loadingDepartments.value=false;if(!id)return;loadingDepartments.value=true;try{const data=await superAdminApi.listDepartments(id);if(version===generation)departments.value=data}catch{if(version===generation)error.value=tr('No se pudieron cargar los departamentos.','Unable to load departments.')}finally{if(version===generation)loadingDepartments.value=false}})
onMounted(async()=>{busy.value=true;try{let page=1,data;do{data=await superAdminApi.listChurches({page:page++});churches.value.push(...data.data)}while(data.next_page_url)}catch{error.value=tr('No se pudieron cargar las iglesias.','Unable to load churches.')}finally{busy.value=false}})
async function open(){if(!module.value)return;busy.value=true;error.value='';const target=module.value.path;try{auth.enterChurch(churches.value.find(c=>c.id===churchId.value));if(view.value==='pastor')auth.enterPastor();if(view.value==='department')auth.enterDepartment(departments.value.find(d=>d.id===departmentId.value));await auth.refreshAccess();if(!auth.canAccess(route.query.module)){auth.exitContext();await auth.refreshAccess();error.value=tr('Esta vista no tiene acceso. Elige otra vista o configura los permisos en Roles y permisos.','This view has no access. Choose another view or configure Roles and permissions.');return}await router.push(target)}catch{error.value=tr('No se pudo abrir el módulo.','Unable to open module.')}finally{busy.value=false}}
</script>
<style scoped>.context-page{max-width:780px}.context-page h1{font-size:21px}.context-page p{color:#586c60;font-size:13px}fieldset{border:1px solid #dfe6e1;border-radius:10px;padding:22px;display:grid;gap:18px;background:white}label{font-size:13px}.form-select{font-size:13px;margin-top:5px}.btn-primary{background:#1f6f5c;border-color:#1f6f5c;width:auto;justify-self:start}</style>
